// The Cloudflare Worker entry (wrangler.jsonc "main"). It answers scanners' probes (/.env,
// /.git/HEAD, /backup.sql …) with a plain 404 before Next.js starts on the request, then hands
// everything else to the OpenNext handler built into .open-next/worker.js
// (`bun run cf:build`). Files in public/ are served by Workers Static Assets before this runs.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";

import { isProbe, PROBE_RESPONSE_INIT } from "./src/lib/probes";

type Fetcher = { fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> };

const worker = {
  async fetch(request: Request, env: unknown, ctx: unknown): Promise<Response> {
    if (isProbe(new URL(request.url).pathname)) return new Response("Not found", PROBE_RESPONSE_INIT);
    return (handler as Fetcher).fetch(request, env, ctx);
  },
};

export default worker;
